    <div class="notification">
        <div class="title">SYSTEM WARNING: RANSOMWARE DETECTED</div>
        <div class="message">
            Your files have been encrypted. Your system is compromised.
            <br>
            You have 24 hours to pay the ransom to regain access.
        </div>
        <div class="timer">
            <div id="timer">24:00:00</div>
        </div>
        <button class="button" onclick="payNow()">PAY NOW</button>
        <div class="disclaimer">
            This is a simulated ransomware notification for training purposes. No real data is at risk.
        </div>
    </div>

    <script>
        // Set up the countdown timer
        let timeLeft = 24 * 60 * 60; // 24 hours in seconds
        let timer = setInterval(function() {
            timeLeft--;
            document.getElementById('timer').textContent = formatTime(timeLeft);

            if (timeLeft <= 0) {
                clearInterval(timer);
                showFinalMessage();
            }
        }, 1000);

        function formatTime(seconds) {
            let hours = Math.floor(seconds / 3600);
            let minutes = Math.floor((seconds % 3600) / 60);
            let remainingSeconds = seconds % 60;
            return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(remainingSeconds).padStart(2, '0')}`;
        }

        function showFinalMessage() {
            alert('Time expired! Access to your files will be restored in 5 seconds.');
            setTimeout(function() {
                window.close();
            }, 5000);
        }

        // Payment button click handler
        function payNow() {
            alert('Payment successful!\nYour files will be decrypted shortly.');
            window.close();
        }
    </script>
</body>
</html>
```

