           let countdown = 24 * 60 * 60; // 24 hours in seconds

           function updateTimer() {
               countdown--;
               document.getElementById('countdown').textContent = `${String(countdown).padStart(2, '0')}:00:00`;
               if (countdown <= 0) {
                   clearInterval(timer);
                   document.getElementById('status').textContent = "Time Expired";
